package com.interview.fraud.ai;
import jakarta.annotation.PostConstruct; import java.time.Instant; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service;
@Service public class PolicyRagService {private final JdbcTemplate jdbc;public PolicyRagService(JdbcTemplate j){jdbc=j;}@PostConstruct void seed(){if(jdbc.queryForObject("SELECT COUNT(*) FROM policy_documents",Long.class)>0)return;UUID d=UUID.randomUUID();jdbc.update("INSERT INTO policy_documents(id,title,version,active,created_at) VALUES(?,?,?,true,?)",d,"Fraud Response Policy","2026.1",Instant.now());add(d,"FRP-4.2","High-value cross-border transactions involving high-risk merchants require senior analyst approval before account freeze or payment block.");add(d,"FRP-5.1","Analysts must compare device, customer history, merchant risk, and transaction velocity. Missing evidence must be stated explicitly.");add(d,"FRP-7.3","No automated model or language model may execute an irreversible customer action. A named human approver and rationale are required.");}private void add(UUID d,String c,String text){jdbc.update("INSERT INTO policy_chunks(id,document_id,citation,content,embedding_json) VALUES(?,?,?,?,?)",UUID.randomUUID(),d,c,text,"[]");}public List<Citation> search(String query){Set<String> q=tokens(query);return jdbc.query("SELECT citation,content FROM policy_chunks",(rs,n)->new Citation(rs.getString(1),rs.getString(2))).stream().sorted(Comparator.comparingInt((Citation c)->overlap(q,tokens(c.content()))).reversed()).limit(3).toList();}private Set<String> tokens(String s){return new HashSet<>(Arrays.asList(s.toLowerCase().replaceAll("[^a-z0-9 ]"," ").split("\\s+")));}private int overlap(Set<String>a,Set<String>b){var x=new HashSet<>(a);x.retainAll(b);return x.size();}public record Citation(String citation,String content){} }
